// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Mitoz, mayoz ve üreme (kolay).
const ozBiology8Kolay = <(String, String, List<String>, String)>[
  ('Kromatinin en küçük paketlenme birimi olan ve yaklaşık 147 baz çiftlik DNA\'nın sekiz histon proteininden oluşan bir çekirdeğe sarılmasıyla oluşan yapı hangisidir?', 'Nükleozom', ['Sentromer', 'Ribozom', 'Kohezin halkası'], 'Nükleozomda DNA, sekiz histondan (oktamer) oluşan çekirdeğe yaklaşık iki tur sarılır; nükleozomlar kromatinin "ipe dizili boncuk" görünümünü verir.'),
  ('Sentromeri kromozomun tam ortasında bulunan ve iki kolu eşit uzunlukta olan kromozom nasıl adlandırılır?', 'Metasentrik', ['Akrosentrik', 'Telosentrik', 'Submetasentrik'], 'Sentromer ortadaysa kollar eşit olur ve kromozom metasentrik adını alır; sentromer uca yaklaştıkça submetasentrik, akrosentrik ve telosentrik adları kullanılır.'),
  ('Sentromerin iki yanında bulunan ve iğ ipliklerinin mikrotübüllerinin doğrudan bağlandığı protein yapısına ne ad verilir?', 'Kinetokor', ['Kiazma', 'Aster', 'Nükleozom'], 'Kinetokorlar sentromerdeki özel DNA üzerine kurulan protein plakalarıdır; her kardeş kromatitin kendi kinetokoru vardır ve mikrotübüller buraya bağlanır.'),
  ('Kromozomların uçlarında bulunan ve kromozomun uçlarının birbirine yapışmasını ve kodlayan genlerin aşınmasını önleyen tekrarlı DNA bölgelerine ne ad verilir?', 'Telomer', ['Sentromer', 'Kinetokor', 'İntron'], 'Telomerler kromozom uçlarını koruyan tekrar dizileridir; her eşlenmede biraz kısalabildikleri için kodlayan genleri bir tampon gibi korurlar.'),
  ('Bir memeli hücresinde G₁ evresinde bir çekirdekteki DNA miktarı 6 pg ise aynı hücrenin G₂ evresindeki DNA miktarı kaç pg olur?', '12', ['3', '6', '24'], 'S evresinde DNA eşlendiği için G₂\'deki DNA miktarı G₁\'dekinin iki katıdır: 6 × 2 = 12 pg.'),
  ('Hücre döngüsünde G₁ evresinin sonunda bulunan ve hücrenin DNA eşlemeye girip girmeyeceğine karar verilen ana kontrol noktası nasıl adlandırılır?', 'G₁/S kontrol noktası', ['Metafaz/anafaz kontrol noktası', 'Telofaz kontrol noktası', 'Sitokinez kontrol noktası'], 'G₁/S (memelilerde kısıtlama noktası) geçildiğinde hücre genellikle döngüyü tamamlamaya yönelir; büyüklük, besin, büyüme faktörü ve DNA hasarı burada denetlenir.'),
  ('Mitoz sırasında bütün kinetokorlar iğ ipliklerine doğru biçimde bağlanmadan anafazın başlamasını engelleyen denetim mekanizmasına ne ad verilir?', 'İğ (iğ montaj) kontrol noktası', ['G₁/S kontrol noktası', 'G₂/M kontrol noktası', 'DNA eşlenmesi (S evresi) kontrol noktası'], 'İğ kontrol noktası, bağlanmamış tek bir kinetokor bile olsa anafazı geciktirir; böylece yavru hücrelere eksik ya da fazla kromozom gitmesi önlenir.'),
  ('Hücre döngüsünü ilerleten protein kinazlar (CDK) etkin olabilmek için hangi düzenleyici proteinlere bağlanmak zorundadır?', 'Siklinlere', ['Histonlara', 'Kohezinlere', 'Tubulinlere'], 'Siklin bağımlı kinazlar adlarından da anlaşılacağı gibi ancak siklinle birleşince etkinleşir; siklin miktarı döngü boyunca artıp azaldığı için CDK etkinliği dalgalanır.'),
  ('Bitki hücrelerinde sitokinez sırasında oluşan hücre plağı nasıl büyür?', 'Ortadan başlayıp kenarlara doğru genişler.', ['Hücre zarının dışarıdan içeri doğru boğumlanmasıyla oluşur.', 'Eski hücre duvarından başlayıp merkeze doğru ilerler.', 'Çekirdeğin içinde oluşup sonra sitoplazmaya taşınır.'], 'Golgi kesecikleri önce iki çekirdeğin arasında, hücrenin ortasında birleşir; plak buradan dışa doğru büyüyerek eski hücre duvarına ulaşır.'),
  ('Normal hücreler kültür kabında birbirine değecek kadar çoğalınca bölünmeyi durdururken kanser hücreleri üst üste yığılarak çoğalmayı sürdürür. Normal hücrelerdeki bu özelliğe ne ad verilir?', 'Yoğunluğa bağlı inhibisyon', ['Kontakt (temas) yoluyla bölünmenin uyarılması', 'Hücre farklılaşması', 'Mitotik ayrılmama'], 'Normal hücreler komşu hücrelerle temas ve azalan büyüme faktörleri nedeniyle bölünmeyi bırakır; kanser hücreleri bu yoğunluğa bağlı inhibisyonu yitirmiştir.'),
  ('Mitoz iğinde, bir kutuptan çıkıp kromozomların kinetokorlarına bağlanan mikrotübüllere ne ad verilir?', 'Kinetokor mikrotübülleri', ['Astral mikrotübüller', 'Kutup (örtüşen) mikrotübülleri', 'Ara filamentler'], 'Kinetokor mikrotübülleri kromozomları yakalayıp hareket ettirir; kutup mikrotübülleri ortada örtüşerek hücreyi uzatır, astral mikrotübüller ise sentrozomdan hücre zarına doğru yayılır.'),
  ('Mitozun hangi evresinde çekirdekçik yeniden belirginleşir ve kromozomlar gevşeyerek kromatin hâline döner?', 'Telofaz', ['Prometafaz', 'Metafaz', 'Anafaz'], 'Telofazda kutuplara ulaşan kromozomların çevresinde çekirdek zarı yeniden oluşur, çekirdekçik görünür olur ve kromozomlar açılarak kromatine dönüşür.'),
  ('Hayvan hücrelerinde sitokinez sırasında oluşan boğumlanma oluğunu daraltan kontraktil halka hangi proteinlerden oluşur?', 'Aktin ve miyozin', ['Tubulin ve dinein', 'Keratin ve kolajen', 'Histon ve kohezin'], 'Hücre zarının altında ekvator düzleminde aktin ve miyozin ipliklerinden oluşan halka kasılarak zarı içeri çeker ve hücreyi ikiye böler.'),
  ('Bitki hücrelerinde sitokinez sırasında hücre plağını oluşturan kesecikler hangi organelden kopar?', 'Golgi aygıtından', ['Kloroplast iç zarlarından', 'Kofullardan', 'Mitokondrilerden'], 'Golgi\'den kopan ve hücre duvarı maddeleri taşıyan kesecikler ekvatorda birleşerek hücre plağını kurar; plak genişleyip eski duvara ulaşır.'),
  ('İnsan derisinin en dış katmanındaki ölü hücrelerin sürekli dökülmesine karşın derinin incelmemesi nasıl açıklanır?', 'Epidermisin taban katmanındaki hücrelerin mitozla sürekli yenilenmesi', ['Ölü hücrelerin yeniden canlanması', 'Dermis hücrelerinin mayozla bölünmesi', 'Kıl köklerinin deri yüzeyine sürekli yeni bir deri katmanı salgılaması'], 'Epidermisin bazal katmanındaki kök hücreler mitozla bölünür; yeni hücreler yukarı itilip keratinleşerek dökülenlerin yerini alır.'),
  ('Kırık bir kemiğin iyileşmesinde kırık bölgesinde yeni kemik dokusunun oluşması temelde hangi olaya dayanır?', 'Kemik yapan hücrelerin ve öncüllerinin mitozla çoğalması', ['Kemik hücrelerinin mayozla bölünmesi', 'Kırık kemik uçlarının bölünmeden kendiliğinden kaynaşması', 'Kanın doğrudan kemiğe dönüşmesi'], 'Kırık iyileşmesinde kemik zarındaki öncül hücreler mitozla çoğalıp osteoblastlara farklılaşır ve yeni kemik matriksi üretir.'),
  ('Soğan kök ucu preparatında kromozomları görünür kılmak için kullanılan boyalardan biri hangisidir?', 'Asetokarmin', ['Fenolftalein', 'İyot-potasyum iyodür', 'Benedict çözeltisi'], 'Asetokarmin ve asetoorsein kromatini koyu boyar; lugol nişasta, Benedict ise indirgen şeker testi için kullanılır.'),
  ('Bir kök ucu preparatında sayılan 500 hücreden 40\'ının mitozun herhangi bir evresinde olduğu görülüyor. Bu dokunun mitotik indeksi yüzde kaçtır?', '8', ['4', '12,5', '40'], 'Mitotik indeks = bölünmekte olan hücre / toplam hücre × 100 = 40 / 500 × 100 = %8.'),
  ('Mitozun kromozomları ve bölünme evrelerini 1882\'de semender hücrelerinde ayrıntılı olarak tanımlayan ve "mitoz" terimini ortaya atan bilim insanı kimdir?', 'Walther Flemming', ['Gregor Mendel', 'Robert Hooke', 'August Weismann'], 'Alman biyolog Walther Flemming, anilin boyalarıyla boyadığı hücrelerde iplik benzeri yapıları gözleyerek bölünmeyi mitoz (Yunanca "iplik") olarak adlandırdı.'),
  ('Profaz I\'de homolog kromozomların sinapsa başladığı alt evre hangisidir?', 'Zigoten', ['Leptoten', 'Diakinez', 'Diploten'], 'Zigotende homologlar yan yana gelip sinaptonemal kompleksle fermuar gibi birbirine bağlanmaya başlar.'),
  ('Diploten evresinde sinaptonemal kompleks çözülüp homologlar birbirinden uzaklaşmaya başladığında, krossing overin gerçekleştiği noktalarda görülen X biçimli bağlantılara ne ad verilir?', 'Kiazma', ['Kinetokor', 'Sentromer', 'Nükleozom'], 'Kiazmalar krossing overin mikroskopta görülebilen izleridir; homologları metafaz I\'e kadar bir arada tutarlar.'),
  ('2n = 12 kromozomlu bir hücre profaz I\'deyken kaç tetrat (bivalent) oluşturur?', '6', ['3', '12', '24'], 'Her homolog çift bir tetrat oluşturur; 2n = 12 ise 6 homolog çift, dolayısıyla 6 tetrat vardır.'),
  ('Anafaz I\'de kutuplara çekilen yapılar için hangisi doğrudur?', 'Homolog kromozomlar ayrılır; her kromozom iki kromatitli olarak gider.', ['Kardeş kromatitler ayrılır; her kutba tek kromatitli kromozomlar gider.', 'Tetratlar bölünmeden bütün olarak tek bir kutba gider.', 'Yalnız eşey kromozomları ayrılır, otozomlar ekvatorda kalır.'], 'Anafaz I\'de kohezin yalnız kollar boyunca çözülür, sentromerdeki kohezin korunur; bu nedenle kromatitler birlikte kalır ve homologlar zıt kutuplara gider.'),
  ('Mayoz I ile mayoz II arasındaki, DNA eşlenmesinin gerçekleşmediği kısa ara döneme ne ad verilir?', 'İnterkinez', ['İnterfaz G₁', 'Diakinez', 'Sitokinez'], 'İnterkinez, mayozun iki bölünmesi arasındaki kısa dönemdir; S evresi bulunmadığından DNA eşlenmez.'),
  ('Mitozda ve mayoz I\'de kromozom sayısının yavru hücrelere nasıl geçtiği karşılaştırıldığında hangisi doğrudur?', 'Mitozda 2n → 2n, mayoz I\'de 2n → n olur.', ['Mitozda 2n → n, mayoz I\'de 2n → 2n olur.', 'İkisinde de 2n → n olur.', 'İkisinde de 2n → 4n olur ve sayı iki katına çıkar.'], 'Mitoz kromozom sayısını korur; mayoz I homologları ayırarak sayıyı yarıya indirir.'),
  ('Bir canlının hangi hücrelerinde mayoz görülmez?', 'Kök ucu meristem hücreleri', ['Çiçeğin başçığındaki polen ana hücreleri', 'Testisteki birincil spermatositler', 'Yumurtalıktaki birincil oositler'], 'Kök ucu meristemi büyümeyi sağlar ve mitozla bölünür; diğerleri gamet ya da spor oluşturmak için mayoz geçirir.'),
  ('Bir kromozom çiftinin her ikisinin de hücrede bulunmadığı (2n−2) duruma ne ad verilir?', 'Nullizomi', ['Monozomi', 'Trizomi', 'Tetrazomi'], '2n−1 monozomi, 2n+1 trizomi, 2n+2 tetrazomi, 2n−2 ise bir çiftin tamamen eksik olduğu nullizomidir.'),
  ('Uygun koşullarda 20 dakikada bir bölünen bir bakteri tek hücreden başlayarak 2 saat sonunda kaç hücreye ulaşır?', '64', ['12', '32', '128'], '2 saat = 120 dakika, 120 / 20 = 6 kuşak; 2⁶ = 64 hücre oluşur.'),
  ('İki paramesyumun geçici olarak yan yana gelip mikronükleus kökenli çekirdeklerini karşılıklı değiş tokuş etmesine ne ad verilir?', 'Konjugasyon', ['Tomurcuklanma', 'Partenogenez', 'Rejenerasyon'], 'Konjugasyonda iki birey sitoplazma köprüsüyle birleşir ve haploit çekirdeklerini değiş tokuş eder; sayı artmaz ama kalıtsal çeşitlilik artar.'),
  ('Bira mayasında ana hücreden bir çıkıntı oluşup içine çekirdeğin bir kopyası geçtikten sonra çıkıntının büyüyerek ayrılmasına ne ad verilir?', 'Tomurcuklanma', ['Konjugasyon', 'Rejenerasyon', 'Partenogenez'], 'Maya hücreleri eşeysiz olarak tomurcuklanır: çekirdek mitozla bölünür, kopyalardan biri küçük çıkıntıya geçer ve tomurcuk zamanla ayrılır.'),
  ('Hidrada tomurcuklanmayla oluşan yavru için hangisi doğrudur?', 'Ana bireyin vücut duvarından mitozla gelişir ve ona kalıtsal olarak eştir.', ['Ana bireyin yumurtasından döllenmeden gelişir ve haploittir.', 'İki hidranın kaynaşmasıyla oluşur ve iki ebeveynden gen alır.', 'Ana bireyin kopan bir dokunacından rejenerasyonla gelişir ve sonra ayrılır.'], 'Hidranın gövdesinde mitozla bir çıkıntı oluşur, küçük bir hidraya dönüşür ve kopar; eşeysiz olduğu için ana bireyle aynı kalıtsal yapıdadır.'),
  ('Küf mantarlarında havadan yayılan sporların eşeysiz üremeye yararı nedir?', 'Çok sayıda, hafif ve dayanıklı olup geniş alana yayılabilmeleri', ['Mayozla oluştukları için her birinin diploit olması', 'Döllenme olmadan çimlenemedikleri için kontrollü üreme sağlamaları', 'Ana bireye bağlı kalıp koloni oluşturmaları'], 'Eşeysiz sporlar mitozla ve çok sayıda üretilir; hafif olduklarından rüzgârla uzaklara taşınır, uygun ortama düşünce yeni miselyum oluşturur.'),
  ('Yumurtanın döllenmeden gelişerek yeni bir birey oluşturmasına ne ad verilir?', 'Partenogenez', ['Tomurcuklanma', 'Konjugasyon', 'Rejenerasyon'], 'Partenogenez (döllenmeden gelişme) arılar, yaprak bitleri, su pireleri ve bazı kertenkelelerde görülür; döllenme olmadan embriyo gelişir.'),
  ('Rejenerasyon yeteneği için genel bir eğilim olarak hangisi doğrudur?', 'Yapısı basit canlılarda yüksek, karmaşık canlılarda düşüktür.', ['Memelilerde en yüksek, süngerlerde en düşüktür.', 'Bütün hayvanlarda yaklaşık aynı düzeydedir.', 'Yalnız omurgalılarda görülür, omurgasız hayvanlarda ise hiç görülmez.'], 'Süngerler, sölenterler ve yassı solucanlarda rejenerasyon çok güçlüdür; kuşlar ve memeliler gibi karmaşık canlılarda ise sınırlı onarımla kalır.'),
  ('İnsanda karaciğerin bir bölümü alındıktan sonra kalan kısmın birkaç hafta içinde özgün kütlesine yakın büyüklüğe ulaşması hangi olaya örnektir?', 'Onarım amaçlı (sınırlı) rejenerasyona', ['Eşeysiz üremeye', 'Partenogeneze', 'Metamorfoza'], 'İnsanda karaciğer, yetişkinlikte de belirgin yenilenme gösteren nadir organlardandır; bu olay üreme değil doku onarımıdır.'),
  ('Bazı deniz solucanları ve yassı solucanların vücutlarını kendiliğinden parçalara ayırması ve her parçanın yeni bir bireye dönüşmesine ne ad verilir?', 'Parçalanma', ['Konjugasyon', 'Partenogenez', 'Tomurcuklanma'], 'Fragmentasyonda canlı kendini parçalara böler ve her parça rejenerasyonla eksik kısımlarını tamamlayarak yeni birey olur.'),
  ('Lale, sümbül ve nergis gibi bitkilerin toprak altındaki, etli yapraklarla çevrili kısa gövdeleriyle çoğalmasında kullanılan yapıya ne ad verilir?', 'Soğan', ['Yumru', 'Rizom', 'Stolon'], 'Soğanda kısa yassı bir gövde etli depo yapraklarıyla sarılıdır; yan tomurcuklardan yeni soğancıklar oluşur.'),
  ('Aşılamada üstüne başka bir bitkinin parçası takılan, köklü alt bitkiye ne ad verilir?', 'Anaç', ['Kalem', 'Çelik', 'Rizom'], 'Aşıda köklü alt kısım anaç, üzerine takılan ve istenen meyveyi verecek dal ya da göz kalem adını alır.'),
  ('Asma ve böğürtlende bir dal bitkiden ayrılmadan toprağa gömülüp köklendirildikten sonra ana bitkiden kesilerek yeni bitki elde edilmesine ne ad verilir?', 'Daldırma', ['Çelikleme', 'Aşılama', 'Tohumlama'], 'Daldırmada dal ana bitkiden beslenirken toprak altında kök oluşturur; köklendikten sonra kesilip bağımsız bitki olur.'),
  ('Kalanşo (Bryophyllum) bitkisinin yaprak kenarlarında oluşan küçük bitkiciklerin toprağa düşüp gelişmesi hangi üreme biçimidir?', 'Yaprakla vejetatif üreme', ['Tohumla eşeyli üreme', 'Sporla eşeyli üreme', 'Partenogenez'], 'Kalanşoda yaprak kenarındaki çentiklerde mitozla oluşan bitkicikler düşüp kök salar; bu, yaprakla eşeysiz üremedir.'),
  ('Doku kültüründe bir bitki parçasından önce oluşan, düzensiz ve farklılaşmamış hücre kütlesine ne ad verilir?', 'Kallus', ['Kambiyum', 'Blastula', 'Endosperm'], 'Besiyerine konan parçadan oksin ve sitokinin etkisiyle farklılaşmamış bir kallus gelişir; hormon oranı değiştirilerek kallustan kök ve sürgün elde edilir.'),
  ('Hücre döngüsünde G₂\'den mitoza geçişte denetlenen başlıca koşul hangisidir?', 'DNA eşlenmesinin tamamlanmış ve hasarsız olması', ['Kardeş kromatitlerin birbirinden ayrılmış olması', 'Çekirdek zarının yeniden oluşmuş olması', 'Homolog kromozomların sinaps yapmış olması'], 'G₂/M kontrol noktasında eşlenmenin bitip bitmediği ve DNA\'da hasar olup olmadığı denetlenir; sorun varsa hücre mitoza girmez.'),
  ('Eşeysiz üremenin bireye ve türe sağladığı avantajlar arasında hangisi yer almaz?', 'Yavrularda yeni gen birleşimleri oluşması', ['Eş bulmaya gerek olmaması', 'Kısa sürede çok yavru üretilebilmesi', 'Ortama uyumlu bir genotipin olduğu gibi korunması'], 'Eşeysiz üremede yavrular ana bireyin kopyasıdır; yeni gen birleşimleri ancak eşeyli üremede mayoz ve döllenmeyle oluşur.'),
  ('Birbirine biçim ve büyüklük bakımından tamamen benzeyen iki gametin kaynaşmasıyla gerçekleşen eşeyli üreme hangisidir?', 'İzogami', ['Anizogami', 'Oogami', 'Partenogenez'], 'İzogamide gametler aynı görünümdedir (bazı Chlamydomonas türleri); gametler farklı büyüklükteyse anizogami, biri büyük ve hareketsiz yumurtaysa oogami adını alır.'),
  ('Büyük, hareketsiz ve besin bakımından zengin bir yumurtanın küçük, hareketli bir spermle döllenmesine dayanan eşeyli üreme türü hangisidir?', 'Oogami', ['İzogami', 'Konjugasyon', 'Tomurcuklanma'], 'İnsan dâhil hayvanların çoğunda ve bitkilerde görülen oogamide yumurta büyük ve hareketsiz, sperm küçük ve hareketlidir.'),
  ('Hem erkek hem dişi üreme organı taşıyan solucan ve salyangoz gibi canlılara ne ad verilir?', 'Hermafrodit canlılar', ['Partenogenetik (döllenmesiz gelişen) canlılar', 'Ayrı eşeyli canlılar', 'Haplodiploit canlılar'], 'Bir bireyde hem testis hem yumurtalık bulunması hermafroditlik olarak adlandırılır; toprak solucanı, salyangoz ve tenya örnektir.'),
  ('Testislerde sperm oluşumunun gerçekleştiği, kıvrımlı yapıdaki kanalcıklara ne ad verilir?', 'Seminifer tüpçükler', ['Fallop tüpleri', 'Nefron kanalcıkları', 'Ter bezi kanalları'], 'Seminifer tüpçüklerin duvarında spermatogonyumlar mitoz ve mayozla bölünerek spermlere dönüşür; tüpçüklerin arasında testosteron yapan Leydig hücreleri bulunur.'),
  ('Spermatogenezde aşağıdaki hücrelerin oluşum sırası hangisinde doğru verilmiştir?', 'Spermatogonyum → birincil spermatosit → ikincil spermatosit → spermatit → sperm', ['Birincil spermatosit → spermatogonyum → spermatit → ikincil spermatosit → sperm', 'Spermatit → spermatogonyum → birincil spermatosit → ikincil spermatosit → sperm', 'Spermatogonyum → spermatit → birincil spermatosit → ikincil spermatosit → sperm'], 'Spermatogonyumlar mitozla çoğalır ve büyüyerek birincil spermatosite dönüşür; mayoz I ikincil spermatositleri, mayoz II spermatitleri verir, spermatitler de farklılaşarak sperme dönüşür.'),
  ('Spermatitlerin bölünmeden, şekil değiştirerek kamçılı spermlere dönüşmesine ne ad verilir?', 'Spermiyogenez', ['Akrozom tepkimesi', 'Oogenez', 'Kapasitasyon'], 'Spermiyogenezde çekirdek yoğunlaşır, Golgi\'den akrozom oluşur, kamçı gelişir ve fazla sitoplazma atılır; bölünme olmaz.'),
  ('İnsanda spermatogenezin başlaması ve sürmesi için hangisi doğrudur?', 'Ergenlikte başlar ve yaşam boyu sürebilir.', ['Doğumdan önce başlar ve doğumda tamamen biter.', 'Yalnız ergenlik döneminde birkaç yıl sürer.', 'Her ay yalnız bir sperm üretilir.'], 'Erkeklerde spermatogonyumlar kök hücre gibi kendini yeniler; bu nedenle ergenlikle başlayan sperm üretimi yaşlılıkta azalsa da yaşam boyu sürebilir.'),
  ('Oogenezde mayoz bölünmelerinde sitoplazmanın eşit dağılmamasının işlevsel önemi nedir?', 'Tek bir yumurtanın büyük ve besince zengin olmasını sağlaması', ['Dört yumurtanın aynı büyüklükte olmasını sağlaması', 'Kutup hücrelerinin de döllenebilmesini ve ikiz oluşumunu kolaylaştırması', 'Yumurtanın kromozom sayısının iki katına çıkması'], 'Eşit olmayan sitokinezle sitoplazmanın neredeyse tamamı tek hücrede kalır; böylece yumurta, embriyonun ilk gelişimi için gereken besini ve organelleri taşır.'),
  ('Oogenezde mayoz bölünmeler sırasında oluşan, çok az sitoplazmalı ve sonunda yok olan küçük hücrelere ne ad verilir?', 'Kutup hücreleri', ['Sertoli (destek) hücreleri', 'Spermatitler', 'Leydig hücreleri'], 'Oositin eşit olmayan bölünmelerinde ayrılan küçük kutup hücreleri genellikle dejenere olur; büyük hücre ise yumurta olur.'),
  ('İnsanda yumurtlama (ovulasyon) sırasında yumurtalıktan atılan hücre hangi aşamadadır?', 'Metafaz II\'de durmuş ikincil oosit', ['Mayozu tamamlamış, haploit ve tek kromatitli olgun yumurta', 'Profaz I\'deki birincil oosit', 'Mitoz geçiren oogonyum'], 'İnsanda ovulasyonla atılan hücre metafaz II\'de bekleyen ikincil oosittir; mayoz II ancak sperm girdiğinde tamamlanır.'),
  ('İnsanda ikincil oositin mayoz II bölünmesini tamamlamasını tetikleyen olay hangisidir?', 'Spermin oosite girmesi', ['Yumurtlamanın başlaması', 'Adet kanamasının başlaması', 'Ergenliğe girilmesi'], 'İkincil oosit metafaz II\'de bekler; döllenme sırasında sperm girince mayoz II tamamlanır, ikinci kutup hücresi atılır ve yumurta çekirdeği sperm çekirdeğiyle birleşir.'),
  ('Bir kız bebeğin yumurtalıklarındaki oogonyumların mitozla çoğalması ne zaman tamamlanır?', 'Doğumdan önce, fetal dönemde', ['Ergenlik başladığında, ilk adet döngüsüyle birlikte', 'Her adet döngüsünde yeniden', 'Menopozdan hemen önce'], 'İnsanda oogonyumlar fetal dönemde mitozla çoğalıp birincil oositlere dönüşür; doğumdan sonra yeni oogonyum oluşmaz, sınırlı bir oosit stoku vardır.'),
  ('Yumurtalıkta gelişen oositi çevreleyen, onu besleyen ve östrojen salgılayan hücre katmanlarıyla birlikte oluşturduğu yapıya ne ad verilir?', 'Folikül', ['Seminifer tüp', 'Epididimis', 'Plasenta'], 'Folikül, oosit ve onu saran granüloza ile teka hücrelerinden oluşur; olgunlaşan folikül yumurtlamada yırtılarak oositi bırakır.'),
  ('Spermin baş kısmının ön ucunda bulunan ve yumurtanın dış katmanlarını eritmeye yarayan enzimleri taşıyan yapıya ne ad verilir?', 'Akrozom', ['Sentriyol', 'Kamçı', 'Orta parça'], 'Akrozom Golgi aygıtından köken alan bir kesedir; içindeki hidrolitik enzimler döllenme sırasında yumurta çevresindeki katmanları geçmeyi sağlar.'),
  ('Spermin orta parçasında yoğun olarak bulunan organel hangisidir ve neden?', 'Mitokondri; kamçı hareketi için ATP sağlamak', ['Ribozom; döllenmede yumurtaya hazır protein aktarmak', 'Kloroplast; enerji üretmek', 'Lizozom; yumurtayı sindirmek'], 'Orta parçada kamçının çevresine sarmal biçimde dizilmiş mitokondriler, yüzme için gereken ATP\'yi üretir.'),
  ('Bir sperm ile bir yumurta hücresi karşılaştırıldığında hangisi doğrudur?', 'Yumurta çok daha büyüktür ve bol sitoplazma ile besin taşır.', ['Sperm çok daha büyüktür ve embriyonun besinini taşır.', 'İkisi de aynı büyüklüktedir ve kamçılıdır.', 'Yumurta kamçılıdır ve hareket eder, sperm ise hareketsizdir.'], 'İnsan yumurtası yaklaşık 0,1 mm çapıyla en büyük insan hücrelerindendir; sperm ise küçük, hareketli ve sitoplazması çok azdır.'),
  ('Spermleri epididimisten alıp idrar-sperm kanalına (üretraya) taşıyan kanal hangisidir?', 'Sperm kanalı (vas deferens)', ['Yumurta kanalı (Fallop tüpü)', 'Üreter', 'Seminifer tüpçük (sperm üretim yeri)'], 'Vas deferens epididimisten başlayıp karın boşluğuna girer ve boşaltım kanalıyla üretraya açılır; vazektomide bu kanal kesilir.'),
  ('Meni sıvısının büyük bölümünü oluşturan ve spermlere enerji kaynağı olarak fruktoz sağlayan bez hangisidir?', 'Sperm keseciği (seminal vezikül)', ['Prostat bezi (koruyucu bez)', 'Cowper bezi', 'Böbreküstü bezi kabuğu'], 'Seminal veziküller meninin yaklaşık %60–70\'ini oluşturan, fruktozca zengin sıvıyı salgılar; fruktoz spermlerin enerji kaynağıdır.'),
  ('Mesanenin hemen altında üretrayı çevreleyen, meniye süt görünümlü ve sitrat ile enzimler içeren bir sıvı katan bez hangisidir?', 'Prostat', ['Seminal vezikül', 'Tiroit', 'Pankreas'], 'Prostat bezi üretrayı çevreler; salgısı meninin bir bölümünü oluşturur. Yaşlı erkeklerde prostat büyümesi idrar akışını zorlaştırabilir.'),
  ('Meninin bazik özellikte olmasının spermler açısından önemi nedir?', 'Vajinanın ve üretranın asitliğini nötrleyerek spermleri korumak', ['Spermlerin kamçısını eritip hızını azaltmak', 'Spermlerin sayısını mitozla artırmak', 'Spermlerin mayoz geçirmesini başlatmak'], 'Spermler asitli ortamda hareket yeteneğini yitirir; meninin bazik salgıları vajinanın asitli ortamını ve üretrada kalan idrar asitliğini dengeler.'),
  ('Erkeklerde hem idrarın hem de meninin dışarı atıldığı ortak kanal hangisidir?', 'Üretra', ['Üreter', 'Vas deferens', 'Epididimis'], 'Üretra mesaneden başlayıp penisin ucuna kadar uzanır; erkekte boşaltım ve üreme sisteminin ortak kanalıdır.'),
  ('Testislerin embriyo döneminde karın boşluğunda geliştikten sonra doğuma yakın torbaya inmemesi durumuna ne ad verilir?', 'Kriptorşidizm', ['Varikosel', 'Fimozis', 'Hidrosefali'], 'Kriptorşidizmde testis karın içinde ya da kasıkta kalır; yüksek sıcaklık sperm üretimini bozduğundan tedavi edilmezse kısırlık riski artar.'),
  ('Yumurta kanalının yumurtalığa bakan geniş ağzındaki parmak benzeri uzantıların işlevi nedir?', 'Yumurtlanan oositi kanala yönlendirmek', ['Spermleri sindirmek', 'Hormon depolamak', 'Embriyoyu rahim duvarına tutturup beslemek'], 'Fimbriya adı verilen uzantılar yumurtalığın yüzeyini süpürür ve atılan oositi yumurta kanalına çeker.'),
  ('Embriyonun rahim yerine yumurta kanalına tutunarak gelişmeye başlamasına ne ad verilir?', 'Ektopik gebelik', ['İkiz gebelik', 'Düşük', 'Erken doğum'], 'Ektopik gebelikte embriyo çoğunlukla yumurta kanalına yerleşir; kanal genişleyemediği için yırtılma riski doğar ve tıbbi müdahale gerekir.'),
  ('Rahmin iç yüzeyini döşeyen, her döngüde kalınlaşan ve döllenme olmazsa dökülen tabakaya ne ad verilir?', 'Endometriyum', ['Miyometriyum', 'Zona pellusida', 'Amniyon'], 'Endometriyum kan damarlarınca zengin rahim iç zarıdır; embriyo buraya tutunur. Rahim duvarının kaslı orta katmanı ise miyometriyumdur.'),
  ('Doğum sırasında bebeği dışarı itecek güçlü kasılmaları yapan rahim katmanı hangisidir?', 'Miyometriyum', ['Endometriyum', 'Perimetriyum', 'Korona radiata'], 'Rahmin kalın düz kas katmanı olan miyometriyum doğumda ritmik ve güçlü kasılmalar yapar.'),
  ('Rahmin vajinaya açılan, gebelik boyunca kapalı kalan ve doğumda genişleyen dar alt bölümüne ne ad verilir?', 'Serviks', ['Fallop tüpü', 'Yumurtalık', 'Klitoris'], 'Serviks gebelik boyunca mukus tıkacıyla kapalı kalarak rahmi korur; doğumda yaklaşık 10 cm açılarak bebeğin geçişine izin verir.'),
  ('Kadın üreme sisteminde kas yapılı, döl yatağı ile dış ortam arasında bağlantı sağlayan ve doğum kanalı olarak da görev yapan organ hangisidir?', 'Vajina', ['Rahim', 'Yumurta kanalı', 'Üretra'], 'Vajina, rahim ağzından dış üreme organlarına uzanan kaslı kanaldır; çiftleşme organı ve doğum kanalıdır.'),
  ('Üreme döngüsünde yumurtlamadan önce foliküllerin geliştiği dönem ile yumurtlamadan sonraki dönem sırasıyla nasıl adlandırılır?', 'Folikül evresi ve luteal evre', ['Luteal evre ve folikül evresi', 'Kanama evresi ve folikül evresi', 'Gebelik evresi ve menopoz evresi'], 'Döngünün ilk yarısı foliküllerin büyüdüğü folikül evresi, yumurtlamadan sonraki yarısı ise sarı cismin etkin olduğu luteal evredir.'),
  ('Yumurtlamadan sonra yumurtanın döllenebilir kalma süresi yaklaşık ne kadardır?', '12–24 saat', ['7–10 gün', '2–3 hafta', '4–5 gün'], 'Atılan ikincil oosit kısa ömürlüdür; döllenme genellikle yumurtlamadan sonraki 12–24 saat içinde yumurta kanalında gerçekleşmelidir.'),
  ('Ergenlik döneminde kızlarda ilk adet kanamasına ne ad verilir?', 'Menarş', ['Menopoz', 'Ovulasyon', 'İmplantasyon'], 'İlk adet kanaması menarş, adet döngülerinin kalıcı olarak sona ermesi ise menopoz olarak adlandırılır.'),
  ('Sperm başı yumurtanın dış katmanına bağlandığında akrozomdaki enzimlerin dışarı salınmasına ne ad verilir?', 'Akrozom tepkimesi', ['Kortikal tepkime', 'Kapasitasyon', 'Fragmentasyon'], 'Akrozom tepkimesinde akrozom zarı sperm zarıyla kaynaşır ve enzimler salınarak yumurtayı çevreleyen katmanda bir yol açılır.'),
  ('Bir sperm yumurtaya girdiğinde yumurtanın zarının altındaki keseciklerin içeriğini dışarı boşaltarak çevredeki katmanı sertleştirmesine ne ad verilir?', 'Kortikal tepkime', ['Akrozom tepkimesi', 'Kapasitasyon', 'Spermiyogenez'], 'Kortikal granüllerin boşalması zona pellusidayı değiştirip sertleştirir; böylece başka spermlerin girmesi engellenir.'),
  ('Kurbağa ve balıkların çoğunda döllenmenin dış ortamda (suda) gerçekleşmesi nedeniyle bu canlılarda hangi özellik beklenir?', 'Çok sayıda yumurta ve sperm bırakılması', ['Tek bir büyük yumurta bırakılması', 'Kabuklu yumurta bırakılması', 'Yavruların anne vücudunda plasentayla beslenmesi'], 'Dış döllenmede gametler suda kaybolur ve yumurtalar korumasızdır; döllenme ve yaşama şansını artırmak için çok sayıda gamet üretilir.'),
  ('Dış döllenme yapan canlılarda üremenin başarılı olması için hangi koşul zorunludur?', 'Gametlerin bırakıldığı ortamın sulu olması', ['Dişinin vücudunda plasenta bulunması', 'Yumurtaların kalın kabukla kaplı olması', 'Erkeğin çiftleşme organına sahip olması'], 'Dış döllenmede spermlerin yumurtaya yüzerek ulaşması gerekir; bu nedenle su ya da çok nemli ortam zorunludur.'),
  ('Yumurta bırakan, embriyosu yumurtanın besiniyle anne vücudu dışında gelişen hayvanlara ne ad verilir?', 'Ovipar', ['Vivipar', 'Ovovivipar', 'Partenogenetik'], 'Ovipar hayvanlarda (kuşlar, çoğu sürüngen ve balık) yumurta dışarı bırakılır ve embriyo vitellusla beslenerek dışarıda gelişir.'),
  ('Yumurtaları anne vücudunda gelişen, ancak embriyosu anneden değil yumurtanın kendi besininden beslenen ve yavruları canlı doğan hayvanlara ne ad verilir?', 'Ovovivipar', ['Ovipar', 'Vivipar', 'Hermafrodit'], 'Ovoviviparlarda (bazı köpekbalıkları, engerek) yumurta anne vücudunda tutulur, embriyo vitellusla beslenir ve yavru canlı olarak doğar.'),
  ('Zigotun ilk mitoz bölünmeleriyle oluşan, büyümeden küçülen hücrelere ne ad verilir?', 'Blastomer', ['Gastrula', 'Neoblast', 'Oosit'], 'Segmentasyon bölünmeleriyle oluşan hücrelere blastomer denir; bölünmeler arasında büyüme olmadığından blastomerler giderek küçülür.'),
  ('Memeli blastosistinin dış hücre katmanı olan ve plasentanın embriyo kısmının oluşumuna katılan yapı hangisidir?', 'Trofoblast', ['İç hücre kütlesi', 'Nöral tüp', 'Arkenteron'], 'Blastosistin dış katmanı trofoblasttır; rahim duvarına tutunmayı sağlar ve koryonla birlikte plasentanın embriyo kısmını oluşturur.'),
  ('Memeli blastosistinde embriyonun kendisini (bütün vücut dokularını) oluşturacak hücre grubu hangisidir?', 'İç hücre kütlesi', ['Trofoblast', 'Korona radiata', 'Kutup hücreleri'], 'İç hücre kütlesi embriyoyu oluşturur; embriyonik kök hücreler de bu bölgeden elde edilir.'),
  ('Embriyoyu ve diğer bütün zarları en dıştan saran, memelilerde plasentanın embriyo kısmını oluşturan zar hangisidir?', 'Koryon', ['Amniyon', 'Allantoyis', 'Vitellus kesesi'], 'Koryon en dıştaki embriyonik zardır; kuşlarda kabuğun altında gaz alışverişine katılır, memelilerde koryon villusları plasentayı oluşturur.'),
  ('İnsan embriyosunda kalp atışlarının ultrasonla saptanabildiği dönem yaklaşık olarak hangisidir?', 'Gebeliğin 6. haftası civarı', ['Gebeliğin 1. haftası', 'Gebeliğin 20. haftası, ilk tekmelerle birlikte', 'Doğumdan hemen önce'], 'İnsanda kalp gelişen ilk işlevsel organlardandır; döllenmeden yaklaşık 3–4 hafta sonra (son adet tarihine göre 6. hafta civarı) atmaya başlar.'),
  ('İnsanda gelişen canlının "embriyo" yerine "fetüs" olarak adlandırılmaya başlandığı dönem hangisidir?', 'Döllenmeden sonraki 8. haftanın sonu', ['Döllenmenin hemen ardından', 'İkinci haftanın sonu', 'Doğumdan bir ay önce, akciğerler olgunlaşınca'], 'İlk 8 haftada temel organların taslakları oluşur (organogenez); 9. haftadan doğuma kadarki dönemde gelişen canlıya fetüs denir.'),
  ('Deniz kaplumbağaları yumurtalarını kuma gömüp kuluçkaya yatmadan ayrılır. Bu yumurtalardaki embriyonun gelişimi için gereken ısı nereden sağlanır?', 'Güneşle ısınan kumdan', ['Annenin vücut ısısından', 'Yumurta kabuğundaki fotosentezden', 'Embriyonun kendi titremesinden'], 'Sürüngenler kuluçka ısısını vücutlarından sağlayamaz; yumurtalar güneşin ısıttığı kumun sıcaklığıyla gelişir.'),
  ('1950\'lerin sonunda gebelikte bulantı için verilen ve binlerce bebekte kol ve bacak gelişim bozukluklarına yol açan ilaç hangisidir?', 'Talidomit', ['Penisilin', 'Aspirin', 'Asetilsalisilik asit'], 'Talidomit felaketi, gebelikte kullanılan ilaçların plasentayı geçerek organogenezi bozabileceğini gösterdi ve ilaç onay süreçlerini değiştirdi.'),
  ('Annenin gebelikte aşırı alkol tüketmesiyle bebekte ortaya çıkan, büyüme geriliği, yüz anomalileri ve zihinsel sorunlarla karakterize durum hangisidir?', 'Fetal alkol sendromu', ['Down sendromu', 'Turner sendromu', 'Rh uyuşmazlığı hastalığı'], 'Alkol plasentayı geçerek gelişen beyin ve dokulara zarar verir; fetal alkol sendromu tamamen önlenebilir bir doğumsal bozukluktur.'),
  ('Doğumun evreleri doğru sırayla hangisinde verilmiştir?', 'Serviksin açılması → bebeğin doğması → plasentanın atılması', ['Plasentanın atılması → rahim ağzının açılması → bebeğin doğması', 'Bebeğin doğması → rahim ağzının açılması → plasentanın atılması', 'Rahim ağzının açılması → plasentanın atılması → bebeğin doğması'], 'Doğum, servikal açılma evresiyle başlar; ardından bebek doğar, son olarak plasenta ve zarlar (son) atılır.'),
  ('Doğumdan sonraki ilk günlerde annenin memelerinden salgılanan, antikorca zengin, sarımsı ilk süte ne ad verilir?', 'Kolostrum', ['Amniyon sıvısı', 'Plazma', 'Lenf'], 'Kolostrum özellikle IgA antikorlarınca zengindir ve yeni doğanın sindirim kanalını mikroplara karşı korur.'),
  ('Tek yumurta ikizleri döllenmeden sonraki hangi olay sonucunda oluşur?', 'Erken embriyonun iki ayrı hücre grubuna bölünmesiyle', ['İki ayrı yumurtanın iki ayrı spermle döllenmesiyle', 'Bir yumurtanın aynı anda iki ayrı spermle döllenip bölünmesiyle', 'İki ayrı spermin kaynaşmasıyla'], 'Tek yumurta ikizlerinde tek zigottan gelişen erken embriyo ikiye ayrılır; ayrılmanın zamanına göre plasenta ortak ya da ayrı olabilir.'),
  ('Çift yumurta ikizlerinin genetik benzerliği için hangisi doğrudur?', 'Normal kardeşler kadar birbirine benzerler.', ['Tek yumurta ikizleri kadar birbirine özdeştirler.', 'Hiç ortak gen taşımazlar.', 'Her zaman aynı eşeyden olurlar.'], 'Çift yumurta ikizleri farklı yumurta ve spermlerden oluşur; genetik olarak aynı anda doğmuş sıradan kardeşler gibidir ve ortalama genlerinin yarısını paylaşırlar.'),
  ('Sperm sayısı ya da hareketi çok düşük olan erkeklerde tek bir spermin ince bir iğneyle doğrudan yumurtanın sitoplazmasına enjekte edildiği yöntem hangisidir?', 'ICSI (mikroenjeksiyon)', ['Amniyosentez', 'Klonlama', 'Vazektomi (kanal bağlama)'], 'ICSI (intrasitoplazmik sperm enjeksiyonu), spermin yumurtaya kendisinin girememesi sorununu doğrudan sperm enjeksiyonuyla aşar.'),
  ('Dünyada tüp bebek yöntemiyle doğan ilk bebek Louise Brown hangi yıl İngiltere\'de dünyaya gelmiştir?', '1978', ['1953', '1969', '1996'], 'Robert Edwards ve Patrick Steptoe\'nun çalışmasıyla ilk tüp bebek 1978\'de doğdu; Edwards 2010\'da Nobel ödülü aldı.'),
  ('Prezervatif (kondom) kullanımının, doğum kontrol haplarından farklı olarak sağladığı ek koruma hangisidir?', 'Cinsel yolla bulaşan enfeksiyonlara karşı korunma', ['Yumurtlamanın tamamen durdurulması', 'Spermlerin üretiminin artırılması', 'Rahim iç zarının kalınlaşması'], 'Kondom fiziksel bir engel olarak hem spermlerin hem de mikroorganizmaların geçişini önler; hormonal yöntemler enfeksiyonlara karşı koruma sağlamaz.'),
  ('Rahim içine yerleştirilen spiral (RİA) temel olarak nasıl gebeliği önler?', 'Döllenmeyi ve embriyonun rahme tutunmasını engelleyerek', ['Testosteron salgısını artırarak', 'Spermlerin mayozunu durdurarak', 'Yumurtalıkları cerrahi olarak tamamen ortadan kaldırarak'], 'Rahim içi araçlar rahim ortamını spermler ve tutunma için elverişsiz hâle getirir; bakırlı spiraller spermlere toksik etki de gösterir.'),
  ('Bir erkeğin meni analizinde sperm sayısı normal ama spermlerin hemen hepsinin hareketsiz olduğu görülüyor. Bu durumda döllenmenin gerçekleşmemesinin en olası nedeni nedir?', 'Spermlerin yumurtaya ulaşamaması', ['Spermlerin diploit olması', 'Yumurtanın mayoz geçirmemesi', 'Meninin bazik olup vajinadaki asitliği nötrlemesi'], 'Spermler rahim ve yumurta kanalı boyunca yüzerek yumurtaya ulaşmak zorundadır; hareketsiz spermler bu yolculuğu tamamlayamaz.'),
  ('Bir çiçekte dişi organı (pistil) oluşturan üç bölüm hangi seçenekte doğru verilmiştir?', 'Tepecik, dişicik borusu ve yumurtalık', ['Başçık, sapçık ve tepecik', 'Çanak yaprak, taç yaprak ve çiçek tablası', 'Yumurtalık, başçık ve nektar bezi'], 'Pistil en üstte polenleri yakalayan tepecik, ortada dişicik borusu ve altta tohum taslaklarını taşıyan yumurtalıktan oluşur.'),
  ('Bir çiçekte en dışta bulunan, genellikle yeşil olan ve tomurcuk dönemindeki çiçeği koruyan yapraklara ne ad verilir?', 'Çanak yapraklar', ['Taç yapraklar', 'Başçıklar', 'Tepecikler'], 'Çanak yaprakların (sepal) bütünü kaliksi oluşturur; çiçek açmadan önce tomurcuğu sarıp korur.'),
  ('Böceklerle tozlaşan çiçeklerde taç yaprakların renkli ve gösterişli olmasının işlevi nedir?', 'Tozlaşmayı sağlayan hayvanları çekmek', ['Fotosentezi artırmak', 'Tohumları rüzgârla uzak yerlere yaymak', 'Polenlerin oluşmasını sağlamak'], 'Renkli taç yapraklar, desenler ve koku tozlayıcıları çiçeğe çeker; rüzgârla tozlaşan çiçeklerde taç yapraklar çoğunlukla küçük ya da yoktur.'),
  ('Bir çiçekte çanak yaprak, taç yaprak, erkek organ ve dişi organın dördü de bulunuyorsa bu çiçek nasıl adlandırılır?', 'Tam çiçek', ['Eksik çiçek', 'Tek eşeyli çiçek', 'Kısır çiçek'], 'Dört temel çiçek kısmının hepsini taşıyan çiçeğe tam çiçek, bunlardan biri ya da birkaçı eksik olana eksik çiçek denir.'),
  ('Kapalı tohumlularda bir mikrospor mitozla bölündüğünde polen tanesi içinde oluşan iki hücre hangileridir?', 'Tüp hücresi ve üreme hücresi', ['Yumurta hücresi ve sinerjit', 'İki kutup çekirdeği', 'Antipot hücresi ve sinerjit hücresi'], 'Mikrosporun mitozuyla büyük tüp (vejetatif) hücresi ve küçük üreme hücresi oluşur; üreme hücresi daha sonra mitozla iki sperm çekirdeği verir.'),
  ('Polen tanesindeki üreme hücresinin mitozla bölünmesi sonucunda ne oluşur?', 'İki sperm çekirdeği', ['Dört mikrospor', 'Bir yumurta hücresi', 'İki kutup çekirdeği ve bir antipot'], 'Üreme (generatif) hücresi polen tüpünde ya da polen içinde mitozla bölünerek çift döllenmede kullanılacak iki sperm çekirdeğini oluşturur.'),
  ('Tohum taslağında mayozla oluşan dört megaspordan genellikle kaçı canlı kalarak embriyo kesesini oluşturur?', 'Biri', ['Dördü', 'İkisi', 'Üçü'], 'Megaspor ana hücresinin mayozuyla oluşan dört haploit megspordan üçü dejenere olur; kalan tek megaspor üç ardışık mitozla embriyo kesesine dönüşür.'),
  ('Embriyo kesesinde mikropilin karşı ucunda bulunan üç hücreye ne ad verilir?', 'Antipot hücreleri', ['Sinerjit hücreleri', 'Yumurta hücreleri', 'Bekçi hücreleri'], 'Embriyo kesesinin kalaza ucundaki üç hücre antipotlardır; döllenmede rol almazlar ve genellikle sonra dejenere olurlar.'),
  ('Polen tüpünün tohum taslağına girdiği, örtülerin (integümentler) arasındaki küçük açıklığa ne ad verilir?', 'Mikropil', ['Stoma', 'Lentisel', 'Hilum'], 'Polen tüpü genellikle mikropilden tohum taslağına girer; tohum olgunlaştığında mikropil, çimlenmede suyun girdiği küçük bir delik olarak kalabilir.'),
  ('Tohum taslağını saran örtüler (integümentler) döllenmeden sonra neye dönüşür?', 'Tohum kabuğuna', ['Meyve etine', 'Endosperme', 'Çeneklere'], 'İntegümentler tohum kabuğunu, yumurtalık duvarı ise meyve kabuğunu (perikarp) oluşturur.'),
  ('Bir polen tanesinin aynı çiçeğin ya da aynı bitkinin başka bir çiçeğinin tepeciğine taşınmasına ne ad verilir?', 'Kendi tozlaşma', ['Çapraz tozlaşma', 'Çift döllenme', 'Partenokarpi'], 'Polenin aynı bireyin çiçeğine taşınması kendi tozlaşma, aynı türün farklı bireyinin çiçeğine taşınması çapraz tozlaşmadır.'),
  ('Bazı bitkilerde tepeciğe düşen polen aynı bireye ait olduğunda polen tüpünün gelişmesi engellenir. Bu mekanizmaya ne ad verilir?', 'Kendine uyuşmazlık', ['Çift döllenme', 'Partenokarpi', 'Apomiksis'], 'Kendine uyuşmazlık, tepeciğin kendi polenini genetik olarak tanıyıp reddetmesidir; çapraz tozlaşmayı zorunlu kılarak çeşitliliği korur.'),
  ('Tepeciğe ulaşan bir polen tanesinden polen tüpünün oluşması hangi olayın başlangıcıdır?', 'Spermlerin yumurtaya taşınması', ['Polenin mayoz geçirmesi', 'Meyvenin olgunlaşması', 'Çanak yaprakların dökülüp meyvenin açığa çıkması'], 'Polen tüpü dişicik borusu içinde büyür ve sperm çekirdeklerini embriyo kesesine taşır; bu sayede kapalı tohumlularda döllenme suya bağımlı değildir.'),
  ('Kapalı tohumlularda çift döllenme sonucunda tohum içinde oluşan iki yapı hangisidir?', 'Zigot (2n) ve endosperm (3n)', ['Zigot (n) ve endosperm (2n)', 'İki ayrı zigot (2n)', 'Polen (n) ve tohum kabuğu (2n)'], 'Bir sperm yumurtayla birleşerek diploit zigotu, diğeri iki kutup çekirdeğiyle birleşerek triploit endospermi oluşturur.'),
  ('Mısır tanesinin besin deposu olan endosperm mısırda ne zaman oluşur?', 'İkinci spermin kutup çekirdekleriyle birleşmesinden sonra', ['Tozlaşmadan önce, yumurtalık duvarından', 'Polenin çimlenmesinden önce, tohum taslağı kabuğundan', 'Mayozdan hemen önce, polen ana hücresinden'], 'Endosperm döllenme ürünüdür; döllenme olmazsa endosperm de gelişmez. Mısır tanesinin nişastalı kısmı bu triploit dokudur.'),
  ('Elma ve armutta yenen etli kısım yumurtalık duvarından değil, büyük ölçüde çiçek tablasından gelişir. Bu tür meyvelere ne ad verilir?', 'Yalancı meyve', ['Gerçek (yumurtalık kökenli) meyve', 'Toplu meyve', 'Kuru meyve'], 'Meyvenin büyük bölümü yumurtalık dışındaki yapılardan (çiçek tablası) gelişirse yalancı meyve denir; çilek ve elma örnektir.'),
  ('Fasulye ve bezelyenin tohumlarını taşıyan, olgunlaşınca iki dikiş yerinden açılan kuru meyveye ne ad verilir?', 'Bakla', ['Kapsül', 'Drupa', 'Üzümsü meyve'], 'Baklagillerin meyvesi tek karpelden gelişir ve iki dikiş yerinden açılarak tohumlarını bırakır.'),
  ('Bir tohumda embriyonun ilk kökünü oluşturacak kısmına ne ad verilir?', 'Radikula (kökçük)', ['Plumula (gövdecik)', 'Endosperm', 'Hilum'], 'Embriyoda radikula kökü, plumula gövde ve yaprakları oluşturur; çimlenmede ilk dışarı çıkan genellikle radikuladır.'),
  ('Fasulye çimlenirken çeneklerin toprak yüzeyine çıkıp bir süre yeşil kalmasına ne ad verilir?', 'Toprak üstü (epigeal) çimlenme', ['Toprak altı (hipogeal) çimlenme', 'Dormansi', 'Partenokarpi'], 'Epigeal çimlenmede hipokotil uzar ve çenekleri toprak üstüne taşır; bezelye ve mısırda ise çenek toprak altında kalır (hipogeal).'),
  ('Bir tohumun çimlenmesinde ilk gerçekleşen olay hangisidir?', 'Tohumun su alarak şişmesi', ['Yaprakların fotosenteze başlaması', 'Çiçek oluşması', 'Kökün toprak yüzeyine çıkması'], 'Çimlenme imbibisyonla, yani tohumun su alıp şişmesiyle başlar; su enzimleri etkinleştirir ve tohum kabuğunun yırtılmasını sağlar.'),
  ('Karayosunlarında sporofit nerede gelişir ve nasıl beslenir?', 'Gametofitin üzerinde gelişir ve kısmen ondan beslenir.', ['Gametofitten ayrı, topraktan bağımsız bir bitki olarak gelişir ve kök salar.', 'Gametofitin içinde gizli kalır ve spor üretmez.', 'Sporofit yoktur; döngü yalnız gametofitten oluşur.'], 'Karayosununun sapçık ve kapsülden oluşan sporofiti, döllenmenin olduğu gametofitin üzerinde gelişir ve su ile besinin bir kısmını ondan alır.'),
  ('Karayosunu sporofitinin ucundaki kapsülde haploit sporlar hangi bölünmeyle oluşur?', 'Mayozla', ['Mitozla', 'Tomurcuklanmayla', 'Konjugasyonla'], 'Kapsül içindeki diploit spor ana hücreleri mayozla bölünerek haploit sporları üretir.'),
  ('Karayosunu sporunun çimlenmesiyle oluşan, ipliksi ve yeşil ilk yapıya ne ad verilir?', 'Protonema', ['Protallus', 'Sorus', 'Kapsül'], 'Spor çimlenince ince yeşil iplikler (protonema) oluşur; protonemadan çıkan tomurcuklar yapraklı gametofit bitkiciklerine dönüşür.'),
  ('Karayosunu ve eğreltilerde yumurta hücresini üreten şişe biçimli dişi organa ne ad verilir?', 'Arkegonyum', ['Anteridyum', 'Sporangiyum', 'Mikropil'], 'Gametofit üzerinde yumurtalar arkegonyumda, kamçılı spermler ise anteridyumda mitozla oluşur.'),
  ('Çam ağacında erkek kozalak ve dişi kozalak için hangisi doğrudur?', 'Erkek kozalak polen, dişi kozalak tohum taslağı üretir.', ['Erkek kozalak tohum, dişi kozalak polen üretir.', 'İkisi de yalnız spor üretir; çamda tohum oluşmaz, çoğalma sporla olur.', 'Erkek kozalak meyve, dişi kozalak çiçek oluşturur.'], 'Çamda küçük erkek kozalaklar bol polen üretir; büyük dişi kozalakların pulları üzerinde açıkta tohum taslakları bulunur.'),
  ('Çam polenlerinin iki yanında bulunan hava keseciklerinin işlevi nedir?', 'Rüzgârla taşınmayı kolaylaştırmak', ['Su içinde yüzerek dişi kozalağa ulaşmayı sağlamak', 'Böcekleri çekmek', 'Tohum kabuğu oluşturmak'], 'Çam polenindeki iki hava kesesi poleni hafifletir ve rüzgârla uzaklara taşınmasını kolaylaştırır.'),
  ('Çamlarda tozlaşma ile döllenme arasındaki süre için hangisi doğrudur?', 'Bir yıldan uzun sürebilir.', ['Birkaç saniye sürer.', 'Tozlaşmadan önce döllenme olur.', 'Kesinlikle aynı gün gerçekleşir.'], 'Çamda polen tüpü çok yavaş gelişir; tozlaşmadan yaklaşık bir yıl sonra döllenme olur ve tohumun olgunlaşması iki yılı bulabilir.'),
  ('Plazmodyum dışındaki birçok tek hücreli parazitin olumsuz koşullarda kalın bir duvarla çevrilerek dayanıklı hâle gelmesine ne ad verilir?', 'Kistleşme', ['Konjugasyon', 'Tomurcuklanma', 'Partenogenez'], 'Amip ve Giardia gibi protistler kuraklık ya da besinsizlikte kist oluşturur; kist uygun ortama gelince açılır ve canlı etkinliğini sürdürür.'),
  ('Bölünmenin her zaman yalnız birey sayısını artırmak için olmadığı bilinir. Aşağıdakilerden hangisi tek hücreli bir canlıda mitozun sonucudur?', 'Yeni birey oluşması', ['Dokunun büyümesi', 'Yaraların onarılması', 'Gamet oluşması'], 'Tek hücrelilerde hücre bölünmesi doğrudan yeni birey oluşturur; doku büyümesi ve onarım çok hücrelilere özgüdür, gamet oluşumu ise mayozla ilişkilidir.'),
  ('Kalıtsal bilginin yalnız eşey hücreleriyle (germ plazması) aktarıldığını, vücut hücrelerinde edinilen değişikliklerin döllere geçmediğini savunan bilim insanı kimdir?', 'August Weismann', ['Jean-Baptiste Lamarck', 'Rudolf Virchow', 'Robert Hooke'], 'Weismann farelerin kuyruklarını kuşaklar boyunca keserek kesik kuyruğun kalıtılmadığını gösterdi ve germ hattı kuramını geliştirdi.'),
  ('1677\'de kendi yaptığı mikroskopla insan ve hayvan menisinde hareketli "küçük hayvancıklar" yani spermleri ilk gözleyen bilim insanı kimdir?', 'Antoni van Leeuwenhoek', ['Robert Hooke', 'Marcello Malpighi', 'Theodor Schwann'], 'Hollandalı Leeuwenhoek tek mercekli güçlü mikroskoplarıyla bakteriler, kırmızı kan hücreleri ve spermler dâhil pek çok mikroskobik yapıyı ilk kez betimledi.'),
  ('Yumurta kanalına adını veren 16. yüzyıl İtalyan anatomisti kimdir?', 'Gabriele Falloppio', ['Regnier de Graaf', 'Andreas Vesalius Bruxellensis', 'Galileo Galilei'], 'Falloppio yumurta kanallarını ayrıntılı biçimde betimlemiş, bu kanallar onun adıyla Fallop tüpleri olarak anılmıştır.'),
  ('Sperm bankalarında spermlerin yıllarca canlı saklanabilmesi için hangi koşul uygulanır?', 'Sıvı azotta yaklaşık −196 °C\'de dondurma', ['Oda sıcaklığında kurutarak saklama', 'Buzdolabında +4 °C\'de bekletme', 'Tuzlu suda kaynatarak saklama'], 'Koruyucu maddelerle karıştırılan spermler sıvı azotta dondurulur; bu sıcaklıkta metabolizma neredeyse tamamen durduğu için yıllarca canlı kalabilir.'),
  ('Sigara dumanındaki kimyasallar ve güneşin morötesi ışınları gibi DNA\'da mutasyona yol açarak kanser riskini artıran etkenlere ne ad verilir?', 'Kanserojen', ['Antibiyotik', 'Hormon', 'Antikor'], 'Kanserojenler DNA\'da hasar ve mutasyonlar oluşturur; proto-onkogen ve tümör baskılayıcı genlerdeki mutasyonlar birikerek kansere yol açabilir.'),
  ('Omurgalı embriyosunda sırt bölgesindeki ektodermin kalınlaşıp içe kıvrılarak bir boru oluşturmasıyla başlayan evreye ne ad verilir?', 'Nörulasyon', ['Gastrulasyon', 'Segmentasyon', 'İmplantasyon'], 'Nörulasyonda notokordun uyarısıyla sırttaki ektoderm nöral plağı oluşturur; plak kıvrılıp kapanarak beyin ve omuriliğe dönüşecek nöral tüpü kurar.'),
  ('Bir embriyonik dokunun salgıladığı sinyallerle komşu dokunun gelişim yönünü belirlemesine ne ad verilir?', 'Embriyonik indüksiyon', ['Segmentasyon', 'Rejenerasyon', 'Partenogenez'], 'İndüksiyonda bir doku diğerinin farklılaşmasını yönlendirir; örneğin göz kadehi üzerindeki ektodermi göz merceği oluşturmaya yönlendirir.'),
  ('Embriyonun bütün hücreleri aynı genleri taşıdığı hâlde kas, sinir ve deri hücrelerinin farklı yapı ve işleve sahip olması nasıl açıklanır?', 'Her hücre tipinde farklı genlerin etkin olması', ['Her hücre tipinin kendine özgü, farklı genleri taşıması', 'Hücrelerin farklı türlerden gelmesi', 'Bazı hücrelerin DNA\'sını tamamen kaybetmesi'], 'Farklılaşmada genler kaybolmaz; hücre tipine göre farklı gen grupları açılıp kapanır ve böylece farklı proteinler üretilir.'),
  ('Kurbağa iribaşında kuyruk geriler, bacaklar çıkar ve solungaçların yerini akciğerler alır. Bu dönüşümü başlatan hormon hangisidir?', 'Tiroksin', ['İnsülin', 'Prolaktin', 'Adrenalin'], 'İki yaşamlılarda başkalaşımı tiroit bezinden salgılanan tiroksin başlatır; tiroksin yetersizse iribaş başkalaşım geçiremez.'),
  ('Böceklerde tam başkalaşımda larvanın ergine dönüşmeden önce geçirdiği, beslenmeden doku yeniden yapılanmasının gerçekleştiği evreye ne ad verilir?', 'Pupa', ['Nimf', 'İribaş', 'Blastula'], 'Tam başkalaşımda larva pupa evresine girer; pupa içinde larva dokuları yıkılıp ergin organları kurulur.'),
  ('Böceklerde larvanın deri değiştirmesini (gömlek değiştirme) başlatan hormon hangisidir?', 'Ekdizon', ['Tiroksin', 'Oksitosin', 'Testosteron'], 'Ekdizon deri değiştirmeyi uyarır; gençlik hormonu yüksekse larva yeni bir larva evresine, düşükse pupa ve ergin evresine geçer.'),
  ('Bir öğrenci "Mitoz yalnız büyüme içindir, üremeyle ilgisi yoktur." diyor. Bu görüşü çürütmek için en uygun örnek hangisidir?', 'Amibin ikiye bölünerek iki yeni birey oluşturması', ['İnsan derisinin yaralanınca onarılması', 'Kemik kırığının iyileşmesi', 'Bebeğin boyunun ve kemiklerinin yıllar içinde uzaması'], 'Tek hücrelilerde mitoz doğrudan üreme yoludur; ayrıca vejetatif üreme ve tomurcuklanmada da yeni bireyler mitozla oluşur.'),
  ('Bir öğrenci mikroskopta bir bitki hücresinde kutuplarda iki kromozom grubu ve ortada oluşmakta olan bir hücre plağı görüyor. Bu hücre hangi evrededir?', 'Telofaz ve sitokinez', ['Profaz', 'Metafaz', 'Prometafaz'], 'Kutuplarda toplanmış kromozomlar telofazı, ortada oluşan hücre plağı ise bitki hücresinin sitokinezini gösterir.'),
  ('Yavru hücrelerin her birinin ana hücreyle aynı kromozomları alabilmesi için mitozdan önce mutlaka hangi olay gerçekleşmelidir?', 'DNA\'nın eşlenmesi', ['Krossing over', 'Homologların ayrılması', 'Döllenme'], 'Her yavru hücreye tam bir takım verebilmek için hücre DNA\'sını S evresinde eşlemiş olmalıdır; mitoz bu kopyaları eşit dağıtır.'),
  ('Bitkilerde hücre bölünmesini uyaran ve doku kültürlerinde mitozu artırmak için kullanılan hormon grubu hangisidir?', 'Sitokininler', ['Absisik asit', 'Etilen', 'Florijen'], 'Sitokininler adlarını sitokinezi (hücre bölünmesini) uyarmalarından alır; oksinle birlikte bitki hücrelerinin bölünmesini düzenler.'),
  ('Tek yumurta ikizleri dışında aynı anne ve babadan doğan iki kardeşin genetik olarak tıpatıp aynı olmasının neredeyse imkânsız olmasının nedeni nedir?', 'Mayoz ve döllenmenin çok sayıda farklı birleşim üretmesi', ['Kardeşlerin farklı türden olması', 'Kardeşlerin farklı sayıda kromozom ve farklı türden gen taşıması', 'Mitozun her kardeşte farklı işlemesi'], 'Bağımsız dağılım, krossing over ve rastgele döllenmenin birlikte ürettiği olası birleşim sayısı o kadar büyüktür ki iki kardeşin aynı genomu alması pratikte olanaksızdır.'),
  ('Mayoz sırasında homolog kromozomların ayrılmasına "redüksiyon" denir. Bu olay kromozom sayısı bakımından hangi sonucu doğurur?', 'Diploit hücreden haploit hücreler oluşur.', ['Haploit hücreden diploit hücreler oluşur.', 'Kromozom sayısı iki katına çıkar.', 'Kromozom sayısı dörtte bire iner.'], 'Homologların birbirinden ayrılmasıyla her yavru hücre her çiftten yalnız bir kromozom alır; 2n\'den n\'ye geçilir.'),
  ('Bir bitkide çiçeğin tepeciği tozlaşmadan önce kesilip atılırsa ne olması beklenir?', 'Döllenme olmadığı için tohum ve meyve oluşmaz.', ['Polen gerekmeden daha büyük ve bol tohumlu meyveler oluşur.', 'Tohumlar polen olmadan normal gelişir.', 'Çiçek hemen yeni bir tepecik yapar.'], 'Tepecik polenin tutunup çimlendiği yerdir; tepecik olmadan polen tüpü oluşmaz, döllenme gerçekleşmez ve partenokarpik olmayan bitkilerde meyve gelişmez.'),
  ('Su içinde yaşayan bazı bitkilerde (örneğin deniz çayırları) polenlerin su akıntısıyla taşınarak tozlaşmanın gerçekleşmesine ne ad verilir?', 'Su ile tozlaşma', ['Rüzgârla tozlaşma', 'Böcekle tozlaşma', 'Kuşla tozlaşma'], 'Su ile tozlaşan bitkilerin polenleri genellikle ipliksi ya da su yüzeyinde yüzecek yapıdadır; böylece akıntıyla dişi çiçeklere ulaşır.'),
  ('İncir ağacının çiçekleri kapalı bir meyve dokusu içinde bulunur. İncirin tozlaşmasını sağlayan canlı hangisidir?', 'İncir arısı', ['Rüzgâr', 'Bal arısı', 'Sinek kuşu'], 'İncir arısı dişileri incirin içindeki açıklıktan girip çiçekleri tozlaştırır ve yumurtalarını bırakır; birçok incir çeşidi bu ilişkiye bağımlıdır.'),
  ('Kuru tohumların yıllarca canlı kalabilmesine olanak tanıyan temel özellik hangisidir?', 'Su oranının ve metabolizma hızının çok düşük olması', ['Sürekli fotosentez yapmaları', 'Hızla mitoz geçirmeleri', 'Tohumların içinde hiç hava ve oksijen bulunmaması'], 'Kuru tohumda su oranı çok düşük olduğu için enzimlerin etkinliği ve solunum en aza iner; bu durum tohumun canlılığını uzun süre korumasını sağlar.'),
  ('Kırmızı çiçekli bir gül çeşidinin çelikle çoğaltılan bütün bireyleri neden aynı renkte çiçek açar?', 'Tümü ana bitkiyle aynı kalıtsal yapıda olduğu için', ['Çelikler mayozla geliştiği için', 'Topraktaki mineraller çiçek rengini belirlediği için', 'Çeliklerin yalnız ışıkta köklenmesi için'], 'Çelikten gelişen bitki ana bitkinin mitozla çoğalan hücrelerinden oluşur; bu nedenle aynı genotipi ve çiçek rengini taşır.'),
  ('Bir patates çiftçisi her yıl tohum yerine yumrunun gözlü parçalarını ekiyor. Bu uygulamanın çiftçiye yararı hangisidir?', 'Ürünün istenen çeşidin özelliklerini korumasıdır.', ['Her yıl farklı ve yeni çeşitler elde etmesidir.', 'Bitkilerin hastalıklara karşı çeşitlilik kazanmasıdır.', 'Yumruların mayozla bölünerek çoğalmasıdır.'], 'Yumru parçalarıyla üretim vejetatif üremedir; döller ana çeşidin klonudur ve verim, tat gibi özellikler korunur.'),
  ('Kuşlarda, sürüngenlerde ve iki yaşamlılarda sindirim, boşaltım ve üreme kanallarının birlikte açıldığı ortak boşluğa ne ad verilir?', 'Kloak', ['Plasenta', 'Epididimis', 'Mesane'], 'Bu hayvanlarda bağırsak, boşaltım kanalları ve üreme kanalları kloak adlı ortak bir odaya açılır; çiftleşmede kloaklar birbirine değer.'),
  ('Bir tavuk yumurtasında sarının (vitellus) yüzeyinde görülen küçük beyaz leke neyi temsil eder?', 'Embriyonun gelişeceği germ diskini', ['Kalsiyum deposunu', 'Yumurtanın küt ucundaki hava odasını', 'Kabuk zarını'], 'Germ diski, yumurta hücresinin sitoplazması ve çekirdeğinin bulunduğu bölgedir; döllenmiş yumurtada segmentasyon burada başlar.'),
  ('Marketten alınan ve kuluçkaya konmayan tavuk yumurtalarından neden civciv çıkmaz?', 'Çoğu döllenmemiştir; kuluçka sıcaklığı da yoktur.', ['Tavuk yumurtalarının kabuğu yoktur.', 'Yumurtalar mitoz geçiremeyecek kadar küçük ve kuru hücrelerdir.', 'Tavuk yumurtalarında vitellus bulunmaz.'], 'Tavuklar horoz olmadan da yumurtlar ve bu yumurtalar döllenmemiştir; döllenmiş olanlar da soğukta saklandığı için embriyo gelişmez.'),
  ('Memeli türlerinin çoğunda dişilerin yalnız belirli dönemlerde çiftleşmeye istekli olduğu ve yumurtlamanın bu döneme denk geldiği döngüye ne ad verilir?', 'Östrus döngüsü', ['Menstrual (adet) döngüsü', 'Hücre döngüsü', 'Krebs döngüsü'], 'Östrus döngüsü olan memelilerde endometriyum dökülmez, geri emilir; dişi yalnız yumurtlama dönemine yakın kızgınlık gösterir.'),
  ('Ergenliğin başlamasını tetikleyen olay olarak hangisi doğru kabul edilir?', 'Hipotalamustan GnRH salgısının artması', ['Mide asidinin artması', 'Kemik iliğinin alyuvar üretimini durdurması', 'Böbreklerin üre üretimini artırması'], 'Ergenlikte hipotalamus GnRH\'yi düzenli salgılamaya başlar; GnRH hipofizden FSH ve LH salgısını artırır, bunlar da gonadları uyarır.'),
  ('Cinsel yolla bulaşan ve bir bakteri tarafından oluşturulan, tedavi edilmezse kısırlığa yol açabilen enfeksiyonlardan biri hangisidir?', 'Klamidya', ['Grip', 'Kızamık', 'Su çiçeği'], 'Klamidya ve bel soğukluğu bakteriyeldir ve antibiyotikle tedavi edilir; tedavisiz kaldıklarında yumurta kanallarında tıkanıklık yaparak kısırlığa neden olabilir.'),
  ('Bir kuş yumurtasının kabuğundaki küçük gözeneklerin embriyo açısından işlevi nedir?', 'Gaz alışverişini sağlamak', ['Besin almayı sağlamak', 'Sperm girişini sağlamak', 'Suyun tamamen dışarı akmasını sağlamak'], 'Kabuk gözenekleri oksijenin girmesini, karbondioksit ve su buharının çıkmasını sağlar; kabuk tamamen kapatılırsa embriyo boğulur.'),
  ('İnsanda bir vücut hücresinde bulunan otozom sayısı kaçtır?', '44', ['22', '23', '46'], 'İnsan vücut hücresindeki 46 kromozomun 44\'ü otozom (22 çift), 2\'si eşey kromozomudur.'),
  ('İnsanda normal bir yumurta hücresinde kaç otozom bulunur?', '22', ['23', '44', '46'], 'Yumurta haploittir ve 23 kromozom taşır: 22 otozom ve bir X kromozomu.'),
  ('Zigottan başlayarak yetişkin bir insan vücudunu oluşturan yaklaşık 30 trilyon hücrenin hemen tamamı hangi bölünmenin ürünüdür?', 'Mitoz', ['Mayoz', 'Tomurcuklanma', 'Konjugasyon'], 'Zigot ardışık mitozlarla çoğalır; vücuttaki bütün somatik hücreler mitozla oluşmuştur, yalnız gametler mayozun ürünüdür.'),
  ('Sperm hücresinin büyük ölçüde sitoplazmasını kaybetmesinin onun işlevine sağladığı yarar nedir?', 'Hafif ve hızlı hareket edebilmesi', ['Embriyoya ilk bölünmeler için bol besin taşıması', 'Daha fazla kromozom taşıması', 'Yumurtayı sindirebilmesi'], 'Sperm yalnız çekirdek, akrozom, mitokondri ve kamçıdan oluşan hafif bir hücredir; bu yapı uzun yolu hızlı yüzmesine uygundur. Besini yumurta sağlar.'),
  ('Spermlerin dişi üreme kanalında döllenme yeteneklerini yaklaşık ne kadar süre koruyabildiği kabul edilir?', 'Birkaç gün', ['Yalnız birkaç dakika', 'Birkaç ay', 'Bir yıl'], 'Spermler dişi üreme kanalında birkaç gün canlı kalabilir; bu nedenle yumurtlamadan birkaç gün önceki ilişki de gebeliğe yol açabilir.'),
  ('Döllenme sırasında spermin yumurtaya girmesiyle birlikte ikincil oositte ne olur?', 'Mayoz II tamamlanır ve ikinci kutup hücresi atılır.', ['Mayoz I yeniden başlar.', 'Yumurta hemen mitozla ikiye bölünür.', 'Kromozom sayısı dörtte bire iner ve çekirdek zarı kaybolur.'], 'Sperm girişi oositi etkinleştirir; metafaz II\'de bekleyen hücre bölünmeyi tamamlar, ikinci kutup hücresini atar ve haploit yumurta çekirdeği oluşur.'),
  ('Döllenmeden sonraki ilk günlerde zigotun bölünerek ilerlediği yer ve tutunma yeri sırasıyla hangisidir?', 'Yumurta kanalında bölünür, rahimde tutunur.', ['Rahimde bölünür, yumurtalıkta tutunur.', 'Yumurtalıkta bölünür, yumurta kanalında tutunur.', 'Vajinada bölünür, rahim ağzında tutunur.'], 'Zigot yumurta kanalında bölünerek yaklaşık 5–7 günde blastosist hâlinde rahme ulaşır ve endometriyuma tutunur.'),
  ('Sezaryen ile doğal doğum arasındaki temel fark hangisidir?', 'Sezaryende bebek karın ve rahim duvarı açılarak çıkarılır.', ['Sezaryende plasenta hiç oluşmaz.', 'Sezaryende gebelik süresi iki katına çıkar.', 'Sezaryende bebek doğum kanalından çıkarılır.'], 'Sezaryen cerrahi bir doğum yöntemidir; bebek doğum kanalından değil karın ve rahim kesisinden çıkarılır.'),
  ('Ultrason incelemelerinin gebelik takibinde yaygın kullanılmasının bir nedeni hangisidir?', 'İyonlaştırıcı ışın olmadan görüntü sağlaması', ['Bebeğin kromozomlarının doğrudan sayılabilmesi', 'Bebeğin cinsiyetini her zaman döllenme anında belirlemesi', 'Plasentanın işlevinin tamamen durdurulması'], 'Ultrason yüksek frekanslı ses dalgalarıyla görüntü oluşturur; X ışınlarından farklı olarak iyonlaştırıcı değildir ve fetüs için güvenli kabul edilir.'),
  ('Hayvancılıkta değerli bir boğanın spermlerinin dondurularak binlerce ineğe yapay olarak verilmesine ne ad verilir?', 'Suni tohumlama', ['Klonlama', 'Doku kültürü', 'Partenogenez'], 'Suni tohumlamada sperm alınıp saklanır ve dişinin üreme kanalına yapay yolla bırakılır; böylece üstün özellikli bir erkekten çok sayıda yavru elde edilir.'),
  ('Kurbağaların yumurtalarını çevreleyen jelatinimsi tabakanın işlevi aşağıdakilerden hangisidir?', 'Yumurtaları korumak ve birbirine bağlı tutmak', ['Yumurtaları kuru karada kurumadan saklamak', 'Yumurtaların fotosentez yapmasını sağlamak', 'Yumurtaların iç döllenmesini sağlamak'], 'Kurbağa yumurtalarının jöle örtüsü suda şişer, yumurtaları kümeler hâlinde tutar ve bir ölçüde avcı ve mekanik etkilere karşı korur; kabuksuz olduklarından suya bağımlıdırlar.'),
  ('Balık yumurtalarının ve sperminin yığın hâlinde suya bırakılmasına balıkçılıkta ne ad verilir?', 'Yumurta dökme', ['Kuluçka', 'Gebelik', 'Tozlaşma'], 'Dış döllenme yapan balıklarda dişiler yumurtalarını, erkekler spermlerini aynı bölgeye bırakır; bu davranış balıkçılıkta yumurta dökme olarak bilinir.'),
  ('İnsan dâhil memelilerde erkek bireyin testislerinden üretilen sperm sayısı ile dişinin ürettiği yumurta sayısı karşılaştırıldığında hangisi doğrudur?', 'Erkek çok daha fazla gamet üretir.', ['Dişi çok daha fazla gamet üretir.', 'İkisi eşit sayıda gamet üretir.', 'Erkek yalnız ergenlikte bir kez gamet üretir.'], 'Erkek her gün milyonlarca sperm üretirken kadın yaşamı boyunca yalnız birkaç yüz yumurta bırakır.'),
  ('Spermatogenezin tamamlanması (spermatogonyumdan olgun sperme) insanda yaklaşık ne kadar sürer?', 'Yaklaşık 2–2,5 ay', ['Birkaç saat', 'Yaklaşık bir hafta', 'Yaklaşık beş yıl'], 'İnsanda spermatogonyumdan sperm oluşması yaklaşık 64–74 gün sürer; ardından spermler epididimiste birkaç gün daha olgunlaşır.'),
  ('Oogenezde birinci kutup hücresi hangi bölünmenin sonunda ayrılır?', 'Mayoz I', ['Mayoz II', 'Oogonyumun mitozu', 'Zigotun ilk mitozu'], 'Birincil oosit mayoz I\'i tamamlayınca büyük ikincil oosit ve küçük birinci kutup hücresi oluşur; ikinci kutup hücresi mayoz II\'de ayrılır.'),
  ('Bir yumurtlama döngüsünde iki farklı folikülden iki ikincil oosit atılır ve ikisi de farklı spermlerle döllenirse ne oluşur?', 'Çift yumurta ikizleri', ['Tek yumurta ikizleri', 'Yapışık ikizler', 'Triploit tek bir embriyo'], 'İki ayrı yumurtanın iki ayrı spermle döllenmesi kalıtsal olarak farklı çift yumurta ikizlerini oluşturur.'),
  ('Gonadlar (testis ve yumurtalık) hem gamet üretir hem de hormon salgılar. Bu nedenle gonadlar için hangi ifade doğrudur?', 'Hem üreme hem de iç salgı (endokrin) organıdır.', ['Yalnız boşaltım organıdır.', 'Yalnız sindirim enzimi üretir.', 'Yalnız sinir sistemine bağlı bir duyu organıdır.'], 'Testis sperm ve testosteron, yumurtalık oosit ile östrojen ve progesteron üretir; bu nedenle gonadlar hem üreme hem endokrin organlarıdır.'),
  ('Karahindiba meyvelerinin üzerindeki şemsiye biçimli ince tüylerin tohumun yayılmasına katkısı nedir?', 'Rüzgârla uzaklara taşınmasını sağlamak', ['Hayvan tüylerine kancalarla yapışıp taşınmasını sağlamak', 'Suda batmasını sağlamak', 'Toprağa gömülmesini sağlamak'], 'Paraşüt gibi işleyen tüyler meyvenin havada uzun süre kalmasını ve rüzgârla kilometrelerce taşınmasını sağlar.'),
  ('Akçaağaç meyvelerinin kanat biçimli uzantılarla düşerken pervane gibi dönmesi bitkiye hangi yararı sağlar?', 'Tohumların ana ağaçtan uzağa düşmesi', ['Tohumların hemen ana ağacın dibinde çimlenmesi', 'Meyvenin kuşlarca yenmesi', 'Polenlerin tepeciğe taşınması'], 'Dönerek düşüş yavaşlar ve rüzgâr meyveyi ağaçtan uzaklaştırır; böylece fideler ana ağaçla ışık ve su için yarışmaz.'),
  ('Fındık, ceviz ve kestane gibi kabuğu sert ve tek tohumlu, açılmayan kuru meyvelere ne ad verilir?', 'Kuru sert meyve', ['Üzümsü (bakka) meyve', 'Bakla', 'Yalancı meyve'], 'Bu meyvelerde perikarp kuru ve sertleşmiştir, olgunlukta açılmaz; içinde genellikle tek tohum bulunur.'),
  ('Bir bitkinin yaşam döngüsünde zigotun diploit sporofite dönüşmesi için hangi bölünme gerçekleşmelidir?', 'Mitoz', ['Mayoz', 'Konjugasyon', 'Tomurcuklanma'], 'Zigot ardışık mitozlarla çok hücreli diploit embriyoyu ve sporofiti oluşturur; kromozom sayısı değişmez.'),
  ('Tipik bir memeli hücresinin yaklaşık 24 saatlik döngüsünde mitoz (M evresi) genellikle ne kadar sürer?', 'Yaklaşık 1 saat', ['Yaklaşık 12 saat', 'Yaklaşık 20 saat', 'Birkaç saniye'], 'Memeli hücrelerinde döngünün büyük bölümü interfazdır; M evresi genellikle yaklaşık bir saat sürer.'),
  ('Mitoz gözlemi için soğan kök ucunun genellikle uç kısmındaki 1–2 mm\'lik bölüm alınır. Bunun nedeni nedir?', 'Bölünen meristem hücrelerinin bu bölgede yoğun olması', ['Bu bölgedeki hücrelerin mayoz geçirmesi', 'Bu bölgede kloroplastların bol bulunması', 'Bu bölgede hücrelerin farklılaşmasını tamamlamış olması'], 'Kök ucunun hemen arkasındaki meristem bölgesinde hücreler sürekli mitoz geçirir; daha gerideki bölgelerde hücreler uzar ve farklılaşır.'),
  ('Kök ucunu koruyan, sürekli aşınan ve meristemden üretilen hücrelerle yenilenen yapıya ne ad verilir?', 'Kök yüksüğü', ['Kök tüyü', 'Endodermis', 'Kambiyum'], 'Kök yüksüğü toprakta ilerlerken aşınan hücreleri sürekli kaybeder; meristemin mitozla ürettiği yeni hücrelerle yenilenir ve meristemi korur.'),
  ('Bir zigotun tek başına eksiksiz bir organizmayı ve plasenta gibi embriyo dışı dokuları oluşturabilmesi hangi özelliği gösterir?', 'Totipotentlik', ['Unipotentlik', 'Multipotentlik', 'Apoptoz'], 'Zigot ve çok erken blastomerler totipotenttir; embriyonun yanı sıra embriyo dışı dokuları da oluşturabilir. İç hücre kütlesi ise pluripotenttir.'),
  ('Mitoz geçiren bir hayvan hücresinde sentrozomlar profazda nasıl bir yol izler?', 'Zıt kutuplara gider ve aralarında iğ iplikleri oluşur.', ['Çekirdeğe girerek kromozomlara bağlanır.', 'Çekirdekçikle birleşerek ribozom üretir.', 'Mayoza geçerek dört parçaya ayrılır.'], 'İnterfazda eşlenen sentrozom çiftleri profazda birbirinden uzaklaşarak kutuplara yerleşir; aralarında mikrotübüllerden oluşan iğ kurulur.'),
  ('Krossing overin mayozda gerçekleşmesi ile mitozda neredeyse hiç görülmemesinin nedeni nedir?', 'Mitozda homolog kromozomların eşleşmemesi', ['Mitozda DNA\'nın eşlenmemesi', 'Mitozda kromozomların kromatitlerinin bulunmaması', 'Mitozun yalnız haploit hücrelerde olması'], 'Krossing over homologların sinaps yapmasını gerektirir; mitozda homologlar bağımsız davranır ve eşleşmez.'),
  ('Bir çiçekli bitkinin yaşam döngüsünde aşağıdaki olaylardan hangisi doğru sıralanmıştır?', 'Tozlaşma → polen tüpü → çift döllenme → tohum ve meyve', ['Çift döllenme → tozlaşma → polen tüpünün oluşması → meyve oluşumu', 'Tohum oluşumu → tozlaşma → çift döllenme → polen tüpü', 'Polen tüpü → tohum oluşumu → tozlaşma → çift döllenme'], 'Polen tepeciğe ulaşır (tozlaşma), tüp oluşturur, spermler çift döllenmeyi gerçekleştirir; ardından tohum taslağı tohuma, yumurtalık meyveye dönüşür.'),
  ('Bal arısının vücudunu kaplayan sık ve dallı tüylerin tozlaşmaya katkısı nedir?', 'Polenlerin tüylere yapışıp başka çiçeklere taşınması', ['Nektarın tüylerde depolanıp sindirilmesi', 'Arının rüzgârla daha hızlı uçması', 'Polenlerin arı vücudunda çimlenmesi'], 'Çiçeğe giren arının tüylerine çok sayıda polen yapışır; arı sonraki çiçeği ziyaret ettiğinde bu polenlerin bir kısmı tepeciğe bulaşır.'),
  ('İnterfazdaki kromatinin gevşek olmasının hücre için önemi nedir?', 'Genlerin okunması ve DNA eşlenmesi için erişilebilir olması', ['Kromozomların iğ iplikleriyle kutuplara kolayca çekilebilmesi için hazırlanması', 'Çekirdek zarının parçalanması', 'Kardeş kromatitlerin ayrılması'], 'Gevşek kromatinde DNA\'ya enzimler kolayca ulaşır; transkripsiyon ve eşlenme bu nedenle interfazda gerçekleşir.'),
  ('Krossing over sırasında DNA\'nın kırılıp yeniden birleşmesi hangi tür olaydır?', 'Homolog rekombinasyon', ['Translasyon', 'Transkripsiyon', 'Glikoliz'], 'Krossing overde kardeş olmayan kromatitlerin DNA\'ları özel enzimlerle kesilir ve karşılıklı olarak yeniden birleştirilir; bu süreç homolog rekombinasyondur.'),
  ('İnsanda ilk adet kanamasından menopoza kadar her döngüde yalnız bir yumurtlama olduğu ve yaklaşık 35 yıl boyunca yılda 13 döngü yaşandığı varsayılırsa bir kadının yaşamı boyunca yaklaşık kaç kez yumurtlama olur?', '455', ['35', '260', '910'], '35 yıl × 13 döngü = 455 yumurtlama; bu sayı doğumda var olan oosit stokunun çok küçük bir bölümüdür.'),
  ('Fasulye tohumunda bulunan ve çimlenmede ilk yaprakları oluşturacak embriyo kısmına ne ad verilir?', 'Plumula', ['Radikula', 'Hilum', 'Mikropil'], 'Embriyonun plumula kısmı gövde ucunu ve ilk gerçek yaprakları, radikula ise kökü oluşturur.'),
  ('Kuş ve sürüngen yavrularının yumurtadan çıkarken gaga ya da burun ucunda bulunan, sonradan düşen küçük sivri çıkıntının işlevi nedir?', 'Yumurta kabuğunu delmeye yardım etmek', ['Yumurtadaki besini sindirmek', 'Annenin sesini algılamak', 'Kabuğu yeniden onarmak'], 'Yumurta dişi denen bu sert çıkıntı yavrunun kabuğu içeriden kırmasını kolaylaştırır; çıkıştan kısa süre sonra düşer ya da körelir.'),
];
